function Pill({value}:{value:string}){return <span className={'pill '+({'Published':'good','Active':'good','Upcoming':'blue','Draft':'muted','Failed':'bad','Expired':'bad','Cancelled':'bad','Processing':'amber','Rescheduled':'amber','Completed':'good'}[value]||'muted')}>{value}</span>};
